1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { and, eq } from "drizzle-orm";
4	import { inboxDismissals, joinRequests } from "@paperclipai/db";
5	import { sidebarBadgeService } from "../services/sidebar-badges.js";
6	import { accessService } from "../services/access.js";
7	import { dashboardService } from "../services/dashboard.js";
8	import { collapseDuplicatePendingHumanJoinRequests } from "../lib/join-request-dedupe.js";
9	import { assertCompanyAccess } from "./authz.js";
10	import { expressHandler } from "../http/express-adapter.js";
11	import type { Handler } from "../http/types.js";
12	import type { StorageService } from "../storage/types.js";
13	
14	function buildDismissedAtByKey(
15	  dismissals: Array<{ itemKey: string; dismissedAt: Date | string }>,
16	): Map<string, number> {
17	  return new Map(
18	    dismissals.map((dismissal) => [dismissal.itemKey, new Date(dismissal.dismissedAt).getTime()]),
19	  );
20	}
21	
22	function buildHandlers(db: Db) {
23	  const svc = sidebarBadgeService(db);
24	  const access = accessService(db);
25	  const dashboard = dashboardService(db);
26	
27	  // server/src/routes/sidebar-badges.ts:25
28	  const getSidebarBadges: Handler = async (ctx) => {
29	    const companyId = ctx.param("companyId") ?? "";
30	    assertCompanyAccess(ctx, companyId);
31	
32	    let canApproveJoins = false;
33	    if (ctx.actor?.type === "board") {
34	      if (ctx.actor.source === "local_implicit" || ctx.actor.isInstanceAdmin) {
35	        canApproveJoins = true;
36	      } else {
37	        canApproveJoins = await access.canUser(companyId, ctx.actor.userId, "joins:approve");
38	      }
39	    } else if (ctx.actor?.type === "agent" && ctx.actor.agentId) {
40	      canApproveJoins = await access.hasPermission(companyId, "agent", ctx.actor.agentId, "joins:approve");
41	    }
42	
43	    const visibleJoinRequests = canApproveJoins
44	      ? collapseDuplicatePendingHumanJoinRequests(
45	        await db
46	          .select({
47	            id: joinRequests.id,
48	            requestType: joinRequests.requestType,
49	            status: joinRequests.status,
50	            requestingUserId: joinRequests.requestingUserId,
51	            requestEmailSnapshot: joinRequests.requestEmailSnapshot,
52	            updatedAt: joinRequests.updatedAt,
53	            createdAt: joinRequests.createdAt,
54	          })
55	          .from(joinRequests)
56	          .where(and(eq(joinRequests.companyId, companyId), eq(joinRequests.status, "pending_approval")))
57	      ).map(({ id, updatedAt, createdAt }) => ({
58	        id,
59	        updatedAt,
60	        createdAt,
61	      }))
62	      : [];
63	
64	    const dismissedAtByKey =
65	      ctx.actor?.type === "board" && ctx.actor.userId
66	        ? await db
67	          .select({ itemKey: inboxDismissals.itemKey, dismissedAt: inboxDismissals.dismissedAt })
68	          .from(inboxDismissals)
69	          .where(and(eq(inboxDismissals.companyId, companyId), eq(inboxDismissals.userId, ctx.actor.userId)))
70	          .then(buildDismissedAtByKey)
71	        : new Map<string, number>();
72	
73	    const badges = await svc.get(companyId, {
74	      dismissals: dismissedAtByKey,
75	      joinRequests: visibleJoinRequests,
76	    });
77	    const summary = await dashboard.summary(companyId);
78	    const hasFailedRuns = badges.failedRuns > 0;
79	    const alertsCount =
80	      (summary.agents.error > 0 && !hasFailedRuns ? 1 : 0) +
81	      (summary.costs.monthBudgetCents > 0 && summary.costs.monthUtilizationPercent >= 80 ? 1 : 0);
82	    badges.inbox = badges.failedRuns + alertsCount + badges.joinRequests + badges.approvals;
83	
84	    return Response.json(badges);
85	  };
86	
87	  return { getSidebarBadges };
88	}
89	
90	export function sidebarBadgeRoutes(db: Db) {
91	  const router = Router();
92	  const { getSidebarBadges } = buildHandlers(db);
93	
94	  const storageSentinel = new Proxy({} as StorageService, {
95	    get(_target, prop) {
96	      throw new Error(`sidebarBadge handler unexpectedly accessed storage.${String(prop)}`);
97	    },
98	  });
99	  const deps = { db, storage: storageSentinel };
100	
101	  router.get("/companies/:companyId/sidebar-badges", expressHandler(getSidebarBadges, deps));
102	
103	  return router;
104	}
